#include <stdio.h>
#include <stdbool.h>

#define N 5
#define M 3

bool is_safe(int alloc[N][M], int need[N][M], int avail[M], int seq[N]) {
    int work[M];
    bool finish[N] = {false};
    for (int j = 0; j < M; j++) work[j] = avail[j];

    for (int count = 0; count < N; count++) {
        bool found = false;
        for (int i = 0; i < N; i++) {
            if (finish[i]) continue;
            bool ok = true;
            for (int j = 0; j < M; j++)
                if (need[i][j] > work[j]) { ok = false; break; }
            if (ok) {
                for (int j = 0; j < M; j++) work[j] += alloc[i][j];
                finish[i] = true;
                seq[count] = i;
                found = true;
                break;
            }
        }
        if (!found) return false;
    }
    return true;
}

int main(void) {
    int alloc[N][M] = {{0,1,0},{2,0,0},{3,0,2},{2,1,1},{0,0,2}};
    int max[N][M]   = {{7,5,3},{3,2,2},{9,0,2},{2,2,2},{4,3,3}};
    int avail[M] = {3,3,2};
    int need[N][M];
    for (int i = 0; i < N; i++)
        for (int j = 0; j < M; j++)
            need[i][j] = max[i][j] - alloc[i][j];

    int seq[N];
    if (is_safe(alloc, need, avail, seq)) {
        printf("safe sequence: ");
        for (int i = 0; i < N; i++) printf("P%d ", seq[i] + 1);
        printf("\n");
    } else {
        printf("unsafe\n");
    }
    return 0;
}
